import { LitElement, html, css } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import "../components/price-history.js"
import { untrustedWarning } from '../components/untrusted-warning.js';
import "./new-price-view.js"
import { sharedStyles } from '../styles.js';

import DOMPurify from 'dompurify';
import { createToast } from '../toast.js';

export class ItemView extends LitElement {
    static properties = {
        selectedServer: { type: Number },
        item: {type: Number},
        itemData: {type: Object},
        user: {type: Object},
        loading: {type: Boolean},
        openPriceRecom: {type: Boolean},
        hasPending: {type: Boolean},
        hasUserPending: {type: Boolean}
    }

    constructor() {
        super()
        this.user = null
        this.itemData = null
        this.selectedServer = null
        this.loading = true;
        this.openPriceRecom = false;
        this.formatter = new Intl.DateTimeFormat("en-US", {dateStyle: 'long', timeStyle: 'medium'})
        this.properPricing = true;
        this.hasPending = false;
        this.hasUserPending = false;

        this.ALLOWED_STYLE_PROPS = {
          color: /^#[0-9a-fA-F]{3,8}$/,
          'font-weight': /^(bold|normal|[1-9]00)$/,
        }
    }

    connectedCallback() {
        super.connectedCallback()

        this.addEventListener('close-recom', (event) => {
            this.openPriceRecom = false;
            this.requestUpdate()
        });

        DOMPurify.addHook('uponSanitizeAttribute', (node, data) => {
      if (data.attrName !== 'style') return;

        const declarations = data.attrValue
          .split(';')
          .map(d => d.trim())
          .filter(Boolean);

        const safeDeclarations = declarations.filter(decl => {
          const [prop, ...rest] = decl.split(':');
          const value = rest.join(':').trim();
          const propName = prop?.trim().toLowerCase();
          const validator = this.ALLOWED_STYLE_PROPS[propName];
          return validator && validator.test(value);
        });

        if (safeDeclarations.length === 0) {
          data.keepAttr = false;
        } else {
          data.attrValue = safeDeclarations.join('; ');
        }
      });

        window.addEventListener('keydown', this._handleGlobalKeydown)
    }

    disconnectedCallback() {
        super.disconnectedCallback()
        window.removeEventListener('keydown', this._handleGlobalKeydown)
    }
    
    async _fetchAll() {
        await this._getItemData()
    }

    async updated(changedProperties) {
        const needFetch = (changedProperties.has('item') || changedProperties.has('selectedServer') && this.item != null && this.selectedServer != null)
        const needPendingCheck = (needFetch || (changedProperties.has('user') && this.selectedServer != null && this.item != null)) && (this.user?.role === 'staff' || this.user?.role === 'admin')

        if (!needFetch && !needPendingCheck) return;
    
        this.loading = true;
    if (needFetch) {
        await this._fetchAll()
    }
    if (needPendingCheck) {
        await this._getPending()
    }
    this.loading = false;
}

    async _getPending() {
        if (this.selectedServer == null || this.item == null) return;
        const url = `/api/checkpending/${this.selectedServer}/${this.item}`
        
        try {
            const response = await fetch(url, {
                method: "GET",
                credentials: "include"
            })
            if (!response.ok) throw new Error("getPending: bad response")

            const result = await response.json()
            this.hasPending = result.isPending
            this.hasUserPending = result.isPersonal
        } catch(e) {
            window.alert("An error occurred while fetching pending prices.")
            throw new Error(e)
        }
    }

    async _getItemData() {
        if (this.selectedServer == null || this.item == null) return;

        const toSendUrl = "/api/item/" + this.selectedServer + "/" + this.item

        try {
        const response = await fetch(toSendUrl, {
            method: "GET",
            credentials: "include"
        })
        if (!response.ok) throw new Error("getItemData: bad response")

        const result = await response.json()
        this.itemData = result.item
    } catch(err) {
        console.error("getItemData error: " + err)
    } finally {
        this.loading = false;
    }
    }

    _handleGlobalKeydown = (e) => {
    if (!this.openPriceRecom && e.key == 'Enter' && (this.user.role == 'staff' || this.user.role == 'admin')) {
        this.openPriceRecom = true;
    }
  }
  
    get lowDataMode() {
      return localStorage.getItem('LDM') === 'true'
    }

  static styles = [sharedStyles, css`
    .center {
    text-align: center;
    }
    
    .dashboard {
        margin-top: 20px;
        display: grid;
        grid-template-columns: max-content 1fr; 
        align-items: stretch; 
        gap: 24px;
        margin: 20px auto 0 auto;
        width: min(900px, 90%);
        box-sizing: border-box;
    }

    .box {
    background-color: var(--color-surface-raised);
    border: 2px solid var(--color-border);
    border-radius: 8px;
    padding: 20px;
    color: var(--color-text);
    text-align: center;
    box-shadow: 0 0 0 1px var(--color-border), 0 4px 16px var(--color-glow);
    }

    .box img {
    object-fit: contain;
      min-width: 50%;
      min-height: 50%;
    }
    
    .profile-column {
        display: block;
        flex-shrink: 0;
    }
    
    .market-column {
        display: flex;
        flex-direction: column;  /* Stack cards vertically down the screen row by row */
        gap: 20px;               /* Clean distribution margins between stacked content elements */
        flex-grow: 1;
        height: 100%;
    }

    .tagbox {
    display: flex;
    gap: 5px;
    flex-wrap: wrap;
    justify-content: center;
    padding-top: 5px;
    padding-bottom: 10px;
    }

    .tag {
    background-color: #bc2bc4;
    color: white;
    font-size: 80%;
    text-transform: uppercase;
    padding: 4px 8px;
    border-radius: 2px;
    }
    
    h1 {
    text-align: center;
    }
    
    .priceAdd {
        font-size: 150%;
    }
    
    .price {
        color: var(--color-price);
        font-weight: bold;
        font-size: 200%;
    }


    .priceinfo {
        
    }

    .untrusted-warning {
        color: var(--wa-color-warning-fill-loud, #b7791f);
        cursor: help;
        font-size: 1rem;
        margin-inline-start: 0.2em;
        vertical-align: -0.15em;
    }
    
    table, th, td {
        border: 1px white solid;
        padding: 10px;
        text-align: center;
    }
    
    table {
        border-collapse: collapse;
        margin: 0 auto;
        margin-top: 20px;
        width: 100%;
        color: white;
    }
    
    .nogrow {
        flex-grow: 0;
    }
    
    .grow {
        flex-grow: 1;
        flex-direction: column;
        display: flex;
    }
    
    .table-scroll-container {
  flex-grow: 1;
  overflow-y: auto;
  max-height: 100%;
}
  `]

  _formatPrice(unformatted) {
        return Number(unformatted).toLocaleString()
    }

    _formatDate(unformatted) {
        const date = new Date(unformatted)
        return this.formatter.format(date)
    }
    
    _openPrice() {
        this.openPriceRecom = true
        this.requestUpdate()
    }

    async _getNextItem(isPrevious) {
        const fetchURL = `/api/itemorder/${isPrevious ? 'previous' : 'next'}?id=${this.item}`
        try {
        const response = await fetch(fetchURL, {
            method: "GET",
            credentials: "include"
        })
        if (!response.ok) return false
        const result = await response.json()
        return Number(result.id)
    } catch(e) {
        console.error(e)
        return false;
    }
    }

    async _back() {
        this.loading = true;
        const id = await this._getNextItem(true)
        if (!id) return this.loading = false;
        this.dispatchEvent(new CustomEvent('nav-requested', {
        bubbles: true,
        composed: true,
        detail: { path: `/~/server/${this.selectedServer}/item/${id}` }
  }));
        this.loading = false;
    }

    async _next() {
        this.loading = true;
        const id = await this._getNextItem(false)
        if (!id) return this.loading = false;
        this.dispatchEvent(new CustomEvent('nav-requested', {
        bubbles: true,
        composed: true,
        detail: { path: `/~/server/${this.selectedServer}/item/${id}` }
  }));
        this.loading = false;
    }

    async _requestNewPrice() {
        if (this.user.role === 'staff' || this.user.role === 'admin') {
            const prompt = window.prompt(`You're already a staff member. This tool is intended for general users. If you actually meant to do this, type 'confirm'.`)
            if (!prompt || prompt.toLowerCase().trim() !== 'confirm') return
        }
        const url = `/api/requestprice/${this.item}/${this.selectedServer}`
        this.loading = true;

        try {
            const response = await fetch(url, {
                method: 'POST',
                credentials: 'include'
            })

            if (!response.ok) {console.error(response); return window.alert('An error occurred.')}
            this.itemData.has_price_request = true;
            createToast("<strong>Success</strong><br>Your price change request was submitted.", {variant: 'success', icon: 'circle-check', allowHtml: true})
        } catch(e) {
            console.error(e)
            createToast("<strong>Uh Oh!</strong><br>Something went wrong while submitting your price request.", {variant: 'danger', icon: 'circle-xmark', allowHtml: true})
        } finally {
            this.loading = false;
        }
    }

     _decodeEscapedUnicode(value) {
    if (typeof value !== 'string') return value
    return value.replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
  }

    _sanitizeHTML(input) {
      return this._decodeEscapedUnicode(DOMPurify.sanitize(input, {
        ALLOWED_TAGS: ['div', 'span', 'br'],
        ALLOWED_ATTR: ['class', 'style'],
      }));
    }

  render() {
    const servers = ["Cherry", "Spirit", "Lotus", "Tulip"]

    if (this.loading || !this.itemData) return html`<div class="center forceGap big-spinner"><wa-spinner></wa-spinner></div>`

    this.properPricing = this.itemData?.recom_timestamp && this.itemData?.username

    return html`
    ${this.openPriceRecom ? html`
        <new-price .itemData=${this.itemData} .selectedServer=${this.selectedServer} .selectedItem=${this.item}></new-price>
        ` : ""}
    <div class="dashboard">
<div class="profile-column">
    <div class="box">
    <wa-button-group orientation="horizontal"><wa-button size="s" variant="brand" ?disabled=${this.item === 1 || this.loading} @click=${this._back}><wa-icon name="angles-left"></wa-icon></wa-button><wa-button size="s" variant="brand" ?disabled=${this.item === 999065 || this.loading} @click=${this._next}><wa-icon name="angles-right"></wa-icon></wa-button></wa-button-group>
    <h1 class="center">${this.itemData.item_name}</h1>
    <div class="tagbox">
        ${this.itemData.tags ? this.itemData.tags.map(tag => {
            return html`<span class="tag">${tag}</span>`
        }) : ""}
    </div>
    ${this.lowDataMode && !this.itemData.tags.includes('spawner') && !this.itemData.tags.includes('currency') ? html`
    <div class="give-preview-text-outer">
        <div class="give-preview-text w-100">
        <div class="give-preview-text-inner text-start" style="text-align: left;">
            ${unsafeHTML(this._sanitizeHTML(this.itemData.item_html))}
        </div>
        </div>
        </div>  
    ` : html`
        <img
        src=${this.itemData.tags.includes('spawner') ? "https://minecraft.wiki/images/Monster_Spawner_JE4.png" : (this.itemData.tags.includes('currency') ? `/src/images/${this.itemData.img_src}` : `https://items.blossomcraft.org/static/images/BlossomCraft_Descriptions/${this.itemData.id}.png`)}
        alt="${this._decodeEscapedUnicode(this.itemData.item_name)}"
        />
    `}
    </div>
</div>

<div class="market-column">
    <div class="box nogrow full">
    <span class="priceAdd">${servers[this.selectedServer]} Price${this.itemData?.is_range ? " Range" : ''}: </span><br><span class="price priceAdd">$${this.properPricing ? `${this._formatPrice(this.itemData.price)}${this.itemData.is_range ? ` to $${this._formatPrice(this.itemData.max_price)}` : ""}` : "-"}</span><br>
    <sub class="priceinfo">${this.properPricing ? html`- ${this.itemData.username}${untrustedWarning(this.itemData.author_id)}<br>${this._formatDate(this.itemData.recom_timestamp)}` : "No price available :("}</sub>

    ${this.user && (this.user.role == "staff" || this.user.role == "admin") && !this.openPriceRecom ?
        html`<br><br>${this.hasPending ?
            html`<wa-callout variant="warning"><wa-icon slot="icon" name="triangle-exclamation"></wa-icon><strong>${this.hasUserPending ? `You already have a pending price submission!` : `Another pending price submission already exists!`}</strong><br>Only submit another if you need to submit a different price.</wa-callout><br>` 
            : ``}<wa-button ?disabled=${this.loading} pill variant="brand" size="s" @click=${this._openPrice}>Recommend New Price (FOR STAFF)</wa-button>` : ""}
    ${this.user ? html`
        <br><br><wa-button ?disabled=${this.loading || this.itemData.has_price_request} pill size="xs" variant="brand" @click=${this._requestNewPrice}>${this.itemData.has_price_request ? html`<wa-icon slot="start" name="check"></wa-icon>Price Request Submitted` : html`<wa-icon slot="start" name="hand"></wa-icon>Request Price${this.properPricing ? ` Change`: ` Set`}`}</wa-button>
        ` : ``}

</div>

<div class="box nogrow">
    <span class="boxheader priceAdd">Price Graph</span><br>
    Coming soon!
</div>

<div class="price-history box grow">
    <span class="priceAdd">Price History</span><br>
    <div class="table-scroll-container">
    <price-history .selectedServer=${this.selectedServer} .itemID=${this.item} .approvedOnly=true></price-history>
    </div>
</div>

</div>
    </div>

    `;
  }
}
customElements.define('item-view', ItemView);